def apply(inputs, premises):
    answer = "Contradiction"
    domestic_scope = bool(inputs["is_domestic_service_in_covered_setting"])
    below_threshold = float(inputs["cash_remuneration_current_or_preceding_year"]) < float(premises["domestic_service_cash_threshold"])
    if domestic_scope and below_threshold:
        answer = "Entailment"
    return {"answer": answer}

